begin;
alter table public.servers add column description text not null default '' check(char_length(description)<=500), add column icon_path text not null default '';
alter table public.servers add constraint server_icon_owned check(icon_path='' or (split_part(icon_path,'/',1)=id::text and icon_path ~ '^[0-9a-f-]+/[0-9a-f-]+\.webp$'));
create table public.server_roles(id uuid primary key default gen_random_uuid(),server_id uuid not null references public.servers on delete cascade,name text not null check(char_length(trim(name)) between 2 and 40),color text not null default '#F23041' check(color ~ '^#[0-9a-fA-F]{6}$'),position integer not null check(position between 1 and 999),permissions text[] not null default '{}',check(permissions <@ array['manage_group','manage_channels','manage_roles','manage_invites']::text[]),unique(server_id,position),unique(server_id,id));
create table public.member_roles(server_id uuid not null,user_id uuid not null,role_id uuid not null,primary key(server_id,user_id,role_id),foreign key(server_id,user_id) references public.server_members on delete cascade,foreign key(server_id,role_id) references public.server_roles(server_id,id) on delete cascade);
create index member_roles_user on public.member_roles(user_id,server_id);
alter table public.server_roles enable row level security;
alter table public.member_roles enable row level security;
create policy roles_read on public.server_roles for select to authenticated using(public.is_member(server_id));
create policy member_roles_read on public.member_roles for select to authenticated using(public.is_member(server_id));
revoke all on public.server_roles,public.member_roles from anon,authenticated;
grant select on public.server_roles,public.member_roles to authenticated;
create function public.member_rank(s uuid,u uuid) returns integer language sql stable security definer set search_path='' as $$select case when exists(select 1 from public.servers where id=s and owner_id=u) then 1000 else coalesce((select max(r.position) from public.server_roles r join public.member_roles m on m.role_id=r.id and m.server_id=r.server_id where m.server_id=s and m.user_id=u),0) end$$;
create function public.has_server_permission(s uuid,p text) returns boolean language sql stable security definer set search_path='' as $$select public.is_member(s) and (public.is_owner(s) or exists(select 1 from public.server_roles r join public.member_roles m on m.role_id=r.id and m.server_id=r.server_id where m.server_id=s and m.user_id=auth.uid() and p=any(r.permissions)))$$;
create function public.save_server(s uuid,new_name text,new_description text,new_icon text) returns void language plpgsql security definer set search_path='' as $$begin
 perform 1 from public.servers where id=s for update;
 if not public.has_server_permission(s,'manage_group') then raise exception 'Sem permissão para editar o grupo'; end if;
 update public.servers set name=trim(new_name),description=trim(new_description),icon_path=new_icon where id=s;
end$$;
create function public.save_server_role(s uuid,r uuid,role_name text,role_color text,role_position integer,role_permissions text[],remove_role boolean default false) returns uuid language plpgsql security definer set search_path='' as $$declare old_rank integer; my_rank integer; p text; result uuid; begin
 perform 1 from public.servers where id=s for update;
 if not public.has_server_permission(s,'manage_roles') then raise exception 'Sem permissão para gerenciar cargos'; end if;
 my_rank:=public.member_rank(s,auth.uid());
 if r is not null then select position into old_rank from public.server_roles where id=r and server_id=s; if not found then raise exception 'Cargo não encontrado'; end if; if old_rank>=my_rank then raise exception 'Você só pode editar cargos abaixo do seu'; end if; end if;
 if remove_role then delete from public.server_roles where id=r and server_id=s; return r; end if;
 if role_position>=my_rank then raise exception 'O cargo precisa ficar abaixo do seu'; end if;
 foreach p in array role_permissions loop if not public.has_server_permission(s,p) then raise exception 'Você não pode conceder uma permissão que não possui'; end if; end loop;
 if r is null then insert into public.server_roles(server_id,name,color,position,permissions) values(s,trim(role_name),role_color,role_position,role_permissions) returning id into result;
 else update public.server_roles set name=trim(role_name),color=role_color,position=role_position,permissions=role_permissions where id=r and server_id=s returning id into result; end if;
 return result;
end$$;
create function public.assign_server_role(s uuid,member_id uuid,r uuid,assigned boolean) returns void language plpgsql security definer set search_path='' as $$declare rank integer; begin
 perform 1 from public.servers where id=s for update;
 if not public.has_server_permission(s,'manage_roles') then raise exception 'Sem permissão para atribuir cargos'; end if;
 rank:=public.member_rank(s,auth.uid());
 if public.member_rank(s,member_id)>=rank then raise exception 'Você só pode gerenciar membros abaixo do seu cargo'; end if;
 if not exists(select 1 from public.server_roles where id=r and server_id=s and position<rank) then raise exception 'Cargo fora da sua hierarquia'; end if;
 if assigned then insert into public.member_roles values(s,member_id,r) on conflict do nothing; else delete from public.member_roles where server_id=s and user_id=member_id and role_id=r; end if;
end$$;
drop policy channels_create on public.channels;
create policy channels_create on public.channels for insert to authenticated with check(public.has_server_permission(server_id,'manage_channels'));
create policy channels_edit on public.channels for update to authenticated using(public.has_server_permission(server_id,'manage_channels')) with check(public.has_server_permission(server_id,'manage_channels'));
grant update(name) on public.channels to authenticated;
alter table public.invites add column max_uses integer check(max_uses between 1 and 10000),add column uses integer not null default 0 check(uses>=0);
drop policy invites_read on public.invites; drop policy invites_create on public.invites; drop policy invites_revoke on public.invites;
create policy invites_read on public.invites for select to authenticated using(public.has_server_permission(server_id,'manage_invites'));
create policy invites_create on public.invites for insert to authenticated with check(public.has_server_permission(server_id,'manage_invites') and expires_at>now() and expires_at<=now()+interval '30 days' and uses=0);
create policy invites_revoke on public.invites for delete to authenticated using(public.has_server_permission(server_id,'manage_invites'));
grant insert(expires_at,max_uses) on public.invites to authenticated;
create or replace function public.join_server(invite_code uuid) returns uuid language plpgsql security definer set search_path='' as $$declare i public.invites; begin
 if auth.uid() is null then raise exception 'Entre na sua conta para aceitar o convite'; end if;
 select * into i from public.invites where code=invite_code for update;
 if i.server_id is null or i.expires_at<=now() then raise exception 'Convite inválido ou expirado'; end if;
 if exists(select 1 from public.server_members where server_id=i.server_id and user_id=auth.uid()) then return i.server_id; end if;
 if i.max_uses is not null and i.uses>=i.max_uses then raise exception 'Este convite atingiu o limite de usos'; end if;
 insert into public.server_members(server_id,user_id) values(i.server_id,auth.uid());
 update public.invites set uses=uses+1 where code=invite_code; return i.server_id;
end$$;
create function public.preview_invite(invite_code uuid) returns table(id uuid,name text,description text,icon_path text,member_count bigint) language sql stable security definer set search_path='' as $$ select s.id,s.name,s.description,s.icon_path,(select count(*) from public.server_members m where m.server_id=s.id) from public.invites i join public.servers s on s.id=i.server_id where i.code=invite_code and i.expires_at>now() and (i.max_uses is null or i.uses<i.max_uses) $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('group-icons','group-icons',true,1048576,array['image/webp']) on conflict(id) do nothing;
create policy group_icons_read on storage.objects for select to authenticated using(bucket_id='group-icons');
create policy group_icons_insert on storage.objects for insert to authenticated with check(bucket_id='group-icons' and (storage.foldername(name))[1] in(select id::text from public.servers where public.has_server_permission(id,'manage_group')) and storage.extension(name)='webp');
create policy group_icons_delete on storage.objects for delete to authenticated using(bucket_id='group-icons' and (storage.foldername(name))[1] in(select id::text from public.servers where public.has_server_permission(id,'manage_group')));
revoke all on function public.member_rank(uuid,uuid),public.has_server_permission(uuid,text),public.save_server(uuid,text,text,text),public.save_server_role(uuid,uuid,text,text,integer,text[],boolean),public.assign_server_role(uuid,uuid,uuid,boolean),public.preview_invite(uuid) from public,anon;
grant execute on function public.member_rank(uuid,uuid),public.has_server_permission(uuid,text),public.save_server(uuid,text,text,text),public.save_server_role(uuid,uuid,text,text,integer,text[],boolean),public.assign_server_role(uuid,uuid,uuid,boolean),public.preview_invite(uuid) to authenticated;
grant execute on function public.preview_invite(uuid) to anon;
commit;
